def F(term,meaning,case,error,why): return dict(term=term,meaning=meaning,case=case,error=error,why=why)

def item(q,r,wrong,why):
    assert len(wrong)==3
    return dict(q=q,r=r,w=[x[0] for x in wrong],e=[x[1] for x in wrong],y=why)

def qa(n,key,level,items,src,**kw): return B.QA(f'g5-{n}-{key}',level,'{X.q}',items,src,**kw)

def number(n,key,prompt,answer,vars,steps,misc,src,unit):
    vars={k:({'expr':v} if isinstance(v,str) else v) for k,v in vars.items()}
    return L.num(f'g5-{n}-{key}',2,prompt,answer,steps,vars=vars,misc=[('m'+str(i),v,e) for i,(v,e) in enumerate(misc)],sources=src,unit=unit)

def unit(n,title,goal,back,onward,overview,case,method,facts,applied,src,prereq=(),figure=None,example=None):
    assert 4<=len(facts)<=6
    banks=[[],[],[]]
    for i,f in enumerate(facts):
        others=[x for j,x in enumerate(facts) if i!=j][:3]
        banks[0].append(item('Which term means '+f['meaning']+'?',f['term'],[(x['term'],'That concerns '+x['meaning']+', rather than the feature asked for.') for x in others],f['why']))
        banks[1].append(item(f['case']+'\nWhich feature is illustrated?',f['term'],[(x['term'],'That identifies '+x['meaning']+'. Read the case for evidence of '+f['meaning']+'.') for x in others],f['why']))
        banks[2].append(item(f['case']+'\nWhich explanation follows?',f['why'],[(x['why'],'That explanation addresses '+x['term']+', rather than the process or relationship in this case.') for x in others],f['meaning']+'.'))
    q0=qa(n,'terms',1,banks[0],src); q1=qa(n,'cases',1,banks[1],src); q2=qa(n,'explain',2,banks[2],src)
    q4=B.SP(f'g5-{n}-assess',3,'Find the incorrect geographical claim.',[f['term']+': '+f['meaning']+'.' for f in facts],[(f['error'],f['why']) for f in facts],src)
    for st,f in zip(q4['pool']['right'],facts): st['explain']='This distinction is correct: '+f['why']+' Look for a claim that reverses the process or makes an unsupported generalisation.'
    sections=[('Your goal and connections','By the end, you should be able to '+goal+'. Builds on: '+back+'. Leads to: '+onward+'.'),('Explain the geography',overview),('Follow the local example or model',case),('Apply and check',method)]
    if figure: sections[2]=(*sections[2],figure)
    L.lesson('geography','geography',n,(f'g5-{n}',title),prereq,re.sub(r'\{(\d+(?:\.\d+)?)\}',r'\1',overview),
      example or L.worked({},facts[0]['case']+' Explain the relationship.',[facts[0]['meaning']+'.',facts[0]['why']],facts[0]['term']),
      [L.card(f'g5-{n}-c1','Distinguish the features before applying them.',[f['term']+': '+f['meaning']+'.' for f in facts],q0['id']),
       L.card(f'g5-{n}-c2','Use the evidence in the example, not a place name alone.',[f['case'] for f in facts],q1['id']),
       L.card(f'g5-{n}-c3','Explain how the process produces the stated effect.',[f['why'] for f in facts],q2['id'])],
      [q0,q1,q2,applied,q4],learn=L.learn(sections,key_words=[(f['term'],f['meaning']) for f in facts],mistake=(facts[0]['error'],facts[0]['meaning']+'.',facts[0]['why'])))
    PATH.append((n,title,goal,back,onward))

def choose(n,rows,src,key="apply",level=2,**kw):
    return qa(n,key,level,[item(q,r,list(zip(w,e)),y) for q,r,w,e,y in rows],src,**kw)

IND=['industry']; TRA=['transport']; COM=['communication']; REG=['trade']

unit(1,'Manufacturing industries','classify an activity from its transformation of inputs into manufactured outputs','Form Four economic activities','industrial clusters and location',
 'Manufacturing changes materials into new products or assembles components. A factory combines material, labour, energy and capital inputs through a process, then distributes outputs. Extraction supplies a material; it is not automatically manufacturing. Transport and retail provide services. A firm may combine these activities, so classify the operation described rather than its company name.',
 'In an invented Douala enterprise, timber is delivered to a workshop, cut and joined into tables, then carried to shops. Making the tables is manufacturing. Felling the trees is primary production; carrying tables is transport; selling them is retail. Waste and energy use also belong in the production account.',
 'Name the input, describe the transformation, then name the output. Check whether the case instead extracts a resource or provides a service. Explain the process before choosing its sector.',[
 F('material input','a substance used to make a product','A furniture workshop receives timber.','An input must always be a finished retail product.','Materials enter the production process.'),
 F('manufacturing process','transformation or assembly that makes a product','Workers cut and join timber into tables.','Cutting and assembling a table is retail alone.','The material is transformed into a manufactured output.'),
 F('manufactured output','a product resulting from transformation or assembly','Finished tables leave the workshop.','The finished table is the same operation as felling a tree.','An output is the result of the specified manufacturing process.'),
 F('service activity','work such as transport or retail rather than making this product','A carrier delivers the finished tables.','Carrying a finished table is itself its manufacture.','Delivery moves the product rather than making it.')],choose(1,[
 ('An invented firm washes, presses and packages fruit as juice. Which operation is manufacturing?','Processing fruit into packaged juice',['Growing the fruit','Carrying sealed cartons','Selling the cartons'],['Growing fruit is primary production.','Carrying goods is a transport service.','Selling is distribution rather than processing.'],'Fruit is transformed into a different marketable product.'),
 ('Ayuk assembles purchased components into radios. Which classification fits assembly?','Manufacturing',['Mining','Retail alone','Passenger transport'],['No mineral is being extracted.','Assembly changes components into a product.','The activity makes radios rather than moving passengers.'],'Manufacturing can assemble components without extracting their materials.'),
 ('Bih compares quarrying stone with making cement. Which operation transforms materials into a manufactured product?','Making cement',['Extracting stone alone','Carrying cement','Advertising cement'],['Extraction obtains a raw material.','Transport moves an already made product.','Advertising supplies a service.'],'The distinction concerns the operation, not whether both firms use machinery.')],IND),IND)

unit(2,'Agglomeration industries','explain a cluster benefit and a possible cost using evidence','manufacturing inputs and services','industrial development and location',
 'Agglomeration is the concentration of related firms and supporting activities. Shared suppliers, specialist workers, infrastructure and knowledge can reduce costs or improve coordination. A cluster is not simply any large city. Congestion, expensive land and pollution can create diseconomies. Benefits depend on actual links, capacity and management; clustering does not guarantee success.',
 'Uganda Investment Authority lists industrial parks including Jinja. A serviced park can bring firms near shared infrastructure, but a proposed advantage is not proof of every firm’s performance. The historic Zollverein complex at Essen in Germany illustrates links between production, rail and worker settlements in an older industrial region. These are different contexts, not identical development paths.',
 'Identify what is shared and explain the mechanism. Then ask whether congestion or pressure on services could offset the saving. Separate a planned park, an operating cluster and a historical industrial landscape.',[
 F('supplier linkage','nearby firms supplying inputs or specialist services','An invented cluster shares a machinery-repair business.','Nearby firms never purchase services from each other.','Proximity can support repeated specialist transactions.'),
 F('labour pool','a concentration of workers with relevant skills','Several workshops recruit locally trained technicians.','A labour pool means all workers are free of cost.','Skills may be easier to find but wages still matter.'),
 F('shared infrastructure','facilities serving several activities','Firms use a common serviced access road.','A shared road proves every factory is profitable.','Infrastructure can support activity without guaranteeing profit.'),
 F('agglomeration diseconomy','a cost caused by excessive concentration or pressure','Delivery vehicles lose time in congestion.','Concentration can only reduce costs.','Congestion can offset some benefits of proximity.')],choose(2,[
 ('Fictional workshops share a repair supplier. Why might clustering help?','Specialist repair services can serve several nearby customers',['All inputs become free','Every firm must make the same product','Competition disappears'],['Shared access still has a cost.','Related firms can perform different operations.','Proximity can increase competition.'],'A shared supplier is a mechanism, not a guarantee.'),
 ('A fictional estate’s access road becomes congested. What should the assessment include?','Delivery delays may offset some shared-service savings',['Congestion is proof of lower journey time','Only the number of buildings matters','Shared facilities remove every cost'],['Congestion adds delay.','Links and performance matter as well as buildings.','Shared facilities do not eliminate all costs.'],'Evaluate both external economies and diseconomies.'),
 ('A map shows many unrelated buildings with no evidence of supplier or labour links. What can be concluded?','Concentration is visible; the claimed linkages need evidence',['All firms share specialist suppliers','All firms have identical profits','The place has no service needs'],['The map alone does not show purchases.','Profit needs financial evidence.','Concentrated activity still needs services.'],'Do not infer every cluster benefit from proximity alone.')],IND),IND,[1])

unit(3,'Industrialisation in less industrialised economies','explain how a stated constraint can limit manufacturing and propose a relevant response','inputs and agglomeration','comparison with advanced industrial profiles',
 'Industrialisation expands manufacturing capabilities and their links to the economy. Reliable electricity, skills, transport, finance and markets can support it. Where any of these is restricted, firms may face higher costs or uncertain output. These are conditions to investigate, not fixed qualities of a population. Resource exports can coexist with limited local processing.',
 'In an invented processing business near Bafoussam, unreliable electricity interrupts machinery and poor roads delay inputs. Improved power reliability addresses one constraint; it does not automatically solve roads or finance. World Bank income groups measure income per person, not industrial structure. In its FY{2027} table Uganda is low income and Cameroon lower-middle income; neither label describes every factory.',
 'Use a chain: constraint, effect on production, possible response, remaining limitation. Avoid treating income labels and industrial categories as interchangeable. Compare evidence within and between places.',[
 F('power constraint','unreliable energy supply interrupting production','Machinery stops during outages in an invented workshop.','Every interruption proves workers lack ability.','Energy reliability can limit output independently of workers’ ability.'),
 F('transport constraint','cost or unreliability in moving inputs and outputs','Inputs arrive late over an unreliable access route.','Building a factory automatically repairs every access road.','Production also depends on links beyond the factory.'),
 F('skills constraint','a shortage of relevant technical capabilities','A firm cannot find technicians to maintain its equipment.','Any training guarantees an immediate job for everyone.','Relevant training can help, but demand and other constraints remain.'),
 F('finance constraint','limited access to funds for viable equipment or working needs','A processor cannot fund suitable machinery.','Natural resources alone provide every firm’s investment funds.','Resources and accessible investment finance are different.')],choose(3,[
 ('A fictional machine repeatedly stops because supply voltage fails. Which response directly targets the stated constraint?','Improve reliable power provision',['Change only the company logo','Assume workers are unwilling','Open an unrelated shop'],['A logo does not restore electricity.','The evidence identifies electricity, not motivation.','An unrelated shop does not power the machine.'],'Match the intervention to the observed mechanism.'),
 ('A fictional processor lacks maintenance skills. Which proposal is most relevant?','Train technicians for the actual equipment',['Assume raw-material exports supply the skills','Measure only the number of roads','Declare every course equally useful'],['Exports do not automatically create maintenance capability.','Road counts do not identify technical skills.','Training relevance matters.'],'Training should address the identified equipment and skill need.'),
 ('A report calls Cameroon a World Bank low-income country and treats that as a manufacturing measure. What correction is needed?','The FY{2027} income label is lower-middle income; industrial structure requires separate evidence',['Income and industry are identical measures','Every country has the same industrial structure','Only factory names determine income classification'],['Income groups and industrial measures answer different questions.','Industrial structures vary.','The income grouping uses income per person.'],'Use the dated income classification accurately and assess industry separately.')],IND),IND,[2])

unit(4,'Advanced industrial profiles: capabilities and changing employment','explain why productivity and employment shares can change differently','constraints on industrialisation','location models and industrial change',
 'An advanced industrial profile may include specialised suppliers, skilled labour, research, reliable networks and high productivity. These features vary across regions and sectors. Higher output per worker can allow output to grow with fewer workers. A fall in manufacturing’s employment share does not by itself prove that manufacturing output fell. Outsourcing and service growth also affect the shares.',
 'In an invented comparison, a plant installs efficient equipment and produces more with fewer labour hours. Its productivity rises. A neighbouring research service may support the plant while being counted in services. The sheet’s AIC wording is treated as a school industrial category, not a World Bank income classification or a claim that every region is equally industrialised.',
 'Ask which indicator is changing: total output, output per worker, number of jobs or share of all jobs. Explain a mechanism and acknowledge uneven benefits, retraining needs and environmental costs.',[
 F('labour productivity','output produced per worker or unit of labour time','An invented plant produces more per labour hour.','Productivity means the total population of the city.','Productivity relates output to labour input.'),
 F('research linkage','connections between investigation, design and production','A laboratory helps a factory improve a process.','Research guarantees every invention will sell.','Design support can improve capability without guaranteeing demand.'),
 F('employment share','manufacturing jobs as a proportion of all employment','Services grow faster while factory job numbers stay unchanged.','A lower job share always proves lower factory output.','A share can fall because its denominator grows.'),
 F('industrial restructuring','changes in industrial activities, organisation or technology','A region moves from older heavy plants towards specialised production.','Industrial restructuring always benefits every worker equally.','New activities and adjustment costs can be uneven.')],choose(4,[
 ('Factory output rises while labour hours fall in an invented record. What follows?','Output per labour hour rises',['Output per labour hour must fall','The record proves every worker benefits','Manufacturing has disappeared'],['More output from less labour raises this ratio.','Distributional outcomes require additional evidence.','The record still describes manufacturing.'],'Separate productivity from employment and welfare.'),
 ('Manufacturing jobs stay constant while service jobs rise. Why can the manufacturing job share fall?','Total employment grows faster than manufacturing employment',['All factories must have closed','Shares ignore the denominator','Every service is manufacturing'],['Constant manufacturing jobs do not imply closure.','The denominator is total employment.','Services and manufacturing are distinct categories.'],'A proportion depends on both numerator and denominator.'),
 ('A region gains research-linked factories while older plants close. Which conclusion is supported?','Its industrial structure is changing',['Every resident gains equally','No retraining can be necessary','Industry has no connection to services'],['Benefits and losses can be uneven.','Changing techniques may require new skills.','Research and other services can support industry.'],'Restructuring describes change, not a guarantee of universal benefit.')],IND),IND,[3])

weber=L.mcq('g5-5-candidate',2,'Invented model: input A is {a} t, input B {b} t, and output {p} t. Every link is {d} km. Transport charge is equal per tonne-kilometre. Which of the listed sites A, B or M has the lowest transport effort?',
 '{a>b && a>p ? "Site A" : b>a && b>p ? "Site B" : "Site M"}',
 [('{a>b && a>p ? "Site B" : "Site A"}','other1'),('{p>a && p>b ? "Site B" : "Site M"}','other2'),('Zero cost at every site','zero')],
 ['At A: ({b} + {p}) × {d} = {(b+p)*d} tonne-km.','At B: ({a} + {p}) × {d} = {(a+p)*d} tonne-km.','At M: ({a} + {b}) × {d} = {(a+b)*d} tonne-km.','The least listed candidate is {answer}. Compare these listed candidates only; this is not a search over every point in space.'],
 vars={'a':{'int':[1,5]},'b':{'int':[1,5]},'p':{'int':[1,5]},'d':{'pick':[10,20,30,40]}},where=['a!=b && a!=p && b!=p'],
 misc=[('other1','Calculate both incoming materials and outgoing product for this candidate; the largest fixed-site weight favours remaining at its own vertex in this equal-distance comparison.'),('other2','Do not choose a site from its name. Compare all three weight-distance totals.'),('zero','Only the material or product at its own site travels no distance. The other flows still travel.')],sources=IND,figure=expression(location_triangle(True)))
unit(5,'Weber’s industrial location model','calculate transport effort for listed candidate sites and state the model’s limits','inputs, outputs and location factors','Cameroon industry and land-use choices',
 'Weber’s classical model examines transport costs, labour costs and agglomeration in choosing an industrial location. A simplified starting model fixes material sources and market, assumes a uniform transport setting and compares weight-distance costs. Labour savings or agglomeration benefits can change the preferred location. A mathematical simplification is not a complete explanation of a real factory site.',
 'Our invented triangle allows only sites A, B and M as candidates. Each link is {20} km. Input weights are {4} t at A and {2} t at B; output is {1} t to M. Candidate A requires {(2+1)*20} tonne-km, B {(4+1)*20}, and M {(4+2)*20}. A is least among these candidates. An unrestricted optimum could lie elsewhere; no such search is claimed.',
 'For each candidate, add every travelling flow’s weight multiplied by distance. A flow at its own origin or market has no link journey. Compare like charges, then state which omitted factors or candidate restrictions matter.',[
 F('material source','a fixed origin of an industrial input','A in the classroom triangle supplies an input.','Every raw material starts at the market.','An input source and product destination can differ.'),
 F('market','a destination where the model’s output is demanded','M receives the finished output.','The market must supply both raw materials.','Demand location differs from material supply.'),
 F('transport effort','the sum of each flow’s weight multiplied by its distance','A candidate calculation includes inputs and finished product.','Only incoming flows ever count.','Both input and output journeys can create transport cost.'),
 F('model assumption','a simplifying condition used in an explanation','Equal charges and fixed sites simplify the invented comparison.','The simplified diagram proves the best real site everywhere.','Real terrain, wages, policies and networks can alter location.')],weber,IND,[1,2,4],figure=expression(location_triangle()),example=L.worked({},'Compare only A, B and M with input weights {4} t and {2} t, output {1} t and equal {20} km links.', ['At A: ({2}+{1}) × {20} = {(2+1)*20} tonne-km.','At B: ({4}+{1}) × {20} = {(4+1)*20} tonne-km.','At M: ({4}+{2}) × {20} = {(4+2)*20} tonne-km.'],'A is least among the listed candidates, with {(2+1)*20} tonne-km.'))

unit(6,'Secondary industries in Cameroon','connect a manufacturing activity to an input, location factor and possible impact','manufacturing and location models','guided land-use decisions',
 'Cameroon’s secondary activities include food processing, wood products, cement and aluminium manufacture. The operation performed determines the sector: growing a crop differs from processing it; felling timber differs from making furniture. Location reflects combinations of materials, power, labour, markets and transport. Industries can create jobs and linkages while also creating waste, emissions or pressure on services.',
 'ALUCAM’s official material identifies its aluminium plant at Edéa. Douala provides a port and market context for industrial links. These examples do not imply every plant uses local minerals or operates at constant output. In a fictional food-processing proposal, reliable crop supply and access to customers matter alongside power, storage and waste management.',
 'Name the actual process, then connect a stated factor to its costs or reliability. Consider an environmental or social effect and the evidence needed to assess it. Do not infer present production statistics from a place name.',[
 F('food processing','manufacture that transforms agricultural products','An invented firm turns fruit into packaged juice.','Growing fruit and making juice are the same sector operation.','Processing transforms agricultural inputs.'),
 F('wood manufacture','making products from wood inputs','A workshop joins timber into doors.','All timber-related activity is forest extraction.','Making doors differs from extracting trees.'),
 F('energy linkage','dependence of a process on suitable power provision','A metal-processing proposal assesses power reliability.','A nearby power source removes every other location factor.','Power is a factor alongside materials, labour and markets.'),
 F('industrial impact','a consequence for people, services or the environment','A fictional processing site provides jobs but needs waste treatment.','Employment makes waste treatment unnecessary.','Benefits and environmental costs can occur together.')],choose(6,[
 ('An invented fruit processor near a producing area still has unreliable power. Which assessment is sound?','Material access helps, but power reliability remains a constraint',['Raw materials solve every constraint','The firm cannot be manufacturing','Waste needs disappear'],['Location advantages do not remove unrelated constraints.','Fruit processing is manufacturing.','Processing can still produce waste.'],'Consider combinations of location factors.'),
 ('A fictional Douala factory uses imported components. What does this show?','Port access can matter even when inputs are imported',['All manufacturing inputs must be mined locally','Imports make assembly a primary activity','A port guarantees profit'],['Industries can import inputs.','Assembly remains manufacturing.','Costs, demand and other factors still matter.'],'A transport link connects sources and production.'),
 ('A proposed wood-products workshop offers jobs beside a stream. What else needs assessment?','Waste and water impacts as well as employment',['Jobs prove no environmental effect','Only the company name matters','Extraction and processing cannot be distinguished'],['Employment does not rule out pollution.','Process and site evidence matter.','The described operation can be classified.'],'Evaluate a benefit and a potential cost separately.')],IND),IND,[5])

PLOTS=[]
for shift in range(4):
    attrs=[dict(flood=False,reserve=False,road=True),dict(flood=False,reserve=True,road=True),dict(flood=True,reserve=False,road=True),dict(flood=False,reserve=False,road=False)]
    plots=[dict(name=chr(65+i),**attrs[(i-shift)%4]) for i in range(4)]
    good=next(p for p in plots if not p['flood'] and not p['reserve'] and p['road'])
    wrong=[p for p in plots if p!=good]
    it=item('Invented map: use only available land outside the flood zone with road access. Which plot meets every classroom rule?', 'Plot '+good['name'], [('Plot '+p['name'],'This plot is a school reserve.' if p['reserve'] else 'This plot lies in the marked flood zone.' if p['flood'] else 'This plot lacks the required road access.') for p in wrong], 'The selected plot is available, outside the marked flood zone and has road access. These are invented classroom rules, not a real planning permit.')
    it['svg']=landuse_map(plots);PLOTS.append(it)
unit(7,'Practical: location of economic activities and land use','read a site map and justify a choice against every stated criterion','industrial location and competing land uses','communication networks and route decisions',
 'A site decision needs evidence about suitability, access and competing land uses. A map can show constraints, but its legend and date determine what can be concluded. In this guided practical, classify each plot against all the given rules, reject unsuitable plots with a reason and record the eligible choice. Real site approval requires further information and authorised decisions.',
 'The invented map marks available land, a school reserve, a flood zone and road access. Our classroom rules require available land outside the marked flood zone with road access. In this example Plot A passes; B is reserved, C is flood-marked and D lacks access. The rules and hazard boundary are teaching inventions, not a survey of a real town.',
 'Draw a record with plot, land status, flood status, access and decision. Read every label; do not choose from colour alone. State a rejection reason for each alternative, then name a real-world uncertainty such as soil, seasonal flooding or community needs.',[
 F('land-use constraint','a competing or reserved use limiting a proposal','The invented map marks a plot as a school reserve.','A reserved site is automatically available for a factory.','A competing designated use can rule out a classroom candidate.'),
 F('hazard evidence','information about a possible damaging process','A plot lies in the map’s marked flood zone.','Any plot close to a road is free of flood risk.','Road access does not remove a separate flood constraint.'),
 F('access criterion','a stated requirement for connection to transport','A plot has the required road connection.','Access alone satisfies every site rule.','Access is only one of the stated criteria.'),
 F('decision record','a comparison showing how each option meets the criteria','Bih records each plot’s land, flood and road status.','A decision requires no explanation of rejected options.','Recording each criterion makes the choice checkable.')],qa(7,'map',2,PLOTS,IND,figure='X.svg'),IND,[6],figure=json.dumps(PLOTS[0]['svg'],ensure_ascii=False))

unit(8,'Communication: information, transport and networks','distinguish information exchange from physical transport and identify network elements','location and access','road and rail development',
 'Communication exchanges information between senders and receivers through a channel. In the wider geographical study, communication systems include transport and telecommunications: transport moves people or goods, while telecommunications transmits information over distance. Networks connect nodes through links. A line on a map shows a connection only within its legend; it does not prove a reliable or affordable service.',
 'In a fictional Buea trading case, Bih phones a supplier to place an order and a carrier later brings the goods. The call exchanges information; the vehicle transports goods. The shop and depot are nodes, while a road is a transport link. A reply can confirm that the message was received and understood.',
 'State what moves, identify its channel and name the connected nodes. Distinguish a connection’s existence from its quality. Check whether a reply gives feedback or whether the message could have been misunderstood.',[
 F('information exchange','sending and receiving a message','Bih phones a supplier with an order.','A telephone call physically carries the ordered sacks.','The message moves through the call; the sacks need transport.'),
 F('physical transport','movement of people or goods between places','A carrier delivers sacks from the depot to the shop.','Delivering goods is identical to sending their price by phone.','Goods and information use different movement processes.'),
 F('network node','a place where links meet or movements begin or end','The depot connects several delivery routes.','A node is always the whole length of a road.','A node is a connecting point rather than a route link.'),
 F('feedback','a response that helps confirm or clarify a message','The supplier repeats the order to check it.','Sending a message guarantees it is understood.','A response can expose misunderstanding.')],choose(8,[
 ('Ayuk sends a delivery address by message, then a truck takes cartons there. What does the message do?','Transmits information to organise transport',['Transports the cartons itself','Removes the need for a route','Proves delivery is complete'],['The cartons still require physical movement.','The vehicle still needs an accessible route.','An instruction is not proof of arrival.'],'Communication can coordinate transport without replacing it.'),
 ('A route map shows several roads meeting at a depot. What is the depot in this network?','A node',['The whole road network','A radio signal','The distance unit'],['A node is one connecting location within the network.','The map describes road connections.','The depot is a place, not a unit.'],'Identify points and links separately.'),
 ('A supplier repeats a spoken order and Bih corrects an item. What function did the reply perform?','Feedback that detected a misunderstanding',['Physical delivery of the item','Proof no channel was used','A substitute for every transport service'],['The reply concerns information, not delivery.','Speech used a channel.','The ordered goods still need transport.'],'Feedback checks interpretation rather than simply assuming success.')],COM),COM,[7])

unit(9,'Development of road transport','explain a road-development factor and calculate a model journey time','network links and access','rail transport and economic impacts',
 'Road development includes route planning, construction, drainage, surfacing and maintenance. Terrain, rainfall, finance, settlement and demand affect what is feasible. A road can provide flexible access to dispersed settlements, but a map line alone does not show its seasonal condition. Drainage and maintenance can be as important as initial construction.',
 'In an invented upland case near Bamenda, rain damages a poorly drained access road. Repairing the surface without drainage may give only temporary improvement. For arithmetic practice, a fictional vehicle travels {60} km at a constant model speed of {30} km per hour: time is {60/30} hours or {60/30*60} minutes. This is not a real journey estimate or speed recommendation.',
 'Connect the factor to the engineering or access problem. In calculations divide distance by speed, then convert hours to minutes. State the constant-speed assumption; real delays, stops and road conditions change travel time.',[
 F('route alignment','the chosen course of a road','A planner compares slopes and settlement connections.','Every straight line on a map is the easiest road to build.','Terrain and access needs can favour a different alignment.'),
 F('drainage','removal or control of water around a road','Side drains reduce water damage in an invented case.','A surface needs no drainage in a rainy area.','Water can weaken a road and interrupt access.'),
 F('maintenance','continued work to keep a road usable','A community reports damage for planned repair.','Construction ends all future repair needs.','Road condition changes through use and weather.'),
 F('accessibility','the ease of reaching places or services','A reliable access road helps a village reach its market.','A drawn road line proves affordable year-round service.','Service quality depends on condition, cost and available transport.')],number(9,'time','Invented constant-speed model: distance {d} km, speed {s} km per hour. Find time in minutes. Ignore stops.','d/s*60',{'s':{'pick':[20,30,40]},'h':{'pick':[1,2,3]},'d':'s*h'},['Time = distance ÷ speed = {d} ÷ {s} = {d/s} hours.','Minutes = {d/s} × {60} = {d/s*60}.'],[('d*s','Multiplying distance by speed does not give time.'),('d/s','That is the time in hours; convert it to minutes.')],TRA,'minutes'),TRA,[8])

unit(10,'Development of rail transport','explain rail’s infrastructure requirements and compute freight tonne-kilometres','road transport and networks','comparison of transport impacts',
 'Rail transport runs on fixed tracks and needs stations or terminals, signalling, maintenance and suitable rolling stock. It can move large flows along established corridors, but goods may still need road transport at the ends. Gradients, construction costs, demand and connections affect development. Rail is not automatically suitable for every small or scattered flow.',
 'Camrail’s network description includes Douala–Yaoundé and Yaoundé–Ngaoundéré connections. No timetable or current capacity is assumed here. In a fictional freight record, {20} tonnes travel {50} km. The work measured as freight tonne-kilometres is {20*50}, not a count of passengers, vehicles or money.',
 'Identify the flow and corridor, then examine terminal access and transfer needs. For freight tonne-kilometres multiply tonnes by kilometres. Do not add different units or interpret the result as tonnes of goods alone.',[
 F('fixed track','a dedicated rail path constraining the route','A train follows rails between terminals.','A train can leave its track to serve any doorstep.','Fixed routes require connecting access for many destinations.'),
 F('terminal','a place where a transport movement begins, ends or transfers','Goods are transferred between a truck and rail wagons.','A terminal removes every handling cost.','Transfers can add handling and coordination needs.'),
 F('freight tonne-kilometre','movement of a tonne of freight through a kilometre','A freight record multiplies load by distance.','Tonnes and kilometres should be added to measure freight movement.','Weight-distance is a product of compatible quantities.'),
 F('corridor demand','a flow concentrated along a transport route','A steady large freight flow uses a rail corridor.','Every remote small shipment needs a new railway.','A fixed network requires demand and cost assessment.')],number(10,'freight','A fictional train carries {t} tonnes for {d} km. Find its freight tonne-kilometres.','t*d',{'t':{'pick':[12,20,30,40]},'d':{'pick':[50,80,100]}},['Freight movement = load × distance.','{t} × {d} = {t*d} tonne-km.'],[('t+d','Adding tonnes and kilometres mixes unlike units.'),('d','Distance alone omits the load.')],TRA,'tonne-km'),TRA,[9])

unit(11,'Economic impacts of road and rail transport','explain a transport benefit and cost without assuming equal outcomes','road and rail development','air and water transport decisions',
 'Reliable transport can connect producers to customers, reduce some distribution costs, widen access to services and support employment. Effects depend on prices, service availability and who can use the link. Construction may also displace activities, divide habitats or increase pollution. More infrastructure alone does not prove a net benefit for every community.',
 'In an invented market record, delivery cost for the same load falls from CFA {12000} to CFA {9000}. The saving is CFA {12000-9000}. This is a cost comparison for an identical shipment, not proof that every retail price falls by the same amount. Market competition, other costs and household access affect the outcome.',
 'State the causal chain from the transport change to the effect. Compare equivalent loads and periods. Subtract the new cost from the old for the saving, and seek evidence about distribution of benefits and environmental costs.',[
 F('market linkage','a connection between producers and potential customers','A fictional reliable route lets growers reach another market.','A new route guarantees every crop sells at a profit.','Access expands opportunities, but demand and costs still matter.'),
 F('distribution cost','the expense of moving and handling goods for delivery','A trader compares cost for the same load before and after a change.','A lower delivery cost proves every other cost falls.','A change in one cost component does not determine every price.'),
 F('social access','people’s ability to reach services and opportunities','A reliable service can help households reach a clinic.','A nearby road guarantees everyone can afford transport.','Physical proximity and affordable usable access differ.'),
 F('external cost','a cost imposed beyond the direct transport transaction','Noise and emissions affect neighbouring homes.','Only fares matter when assessing a route.','Some costs are borne by people outside the transaction.')],number(11,'saving','Invented identical-shipment record: old delivery cost CFA {old}; new cost CFA {new}. How many CFA francs are saved?','old-new',{'new':{'pick':[4000,6000,8000]},'saving':{'pick':[1000,2000,3000]},'old':'new+saving'},['Saving = old cost − new cost.','CFA {old} − CFA {new} = CFA {old-new}.'],[('old+new','Adding costs does not measure the reduction.'),('new','That is the remaining cost, not the saving.')],TRA,'CFA francs'),TRA,[9,10])

unit(12,'Air and water transport','choose a mode for a stated cargo and explain the trade-off','road and rail impacts','specialised transport and pipelines',
 'Air transport can serve urgent, light or high-value flows but needs airports, suitable aircraft and connecting services. Water transport can suit large non-urgent freight flows where ports and navigable routes exist, but terminal handling and onward movement matter. Neither is always cheapest or fastest for every complete journey. Cargo needs, connections and reliability determine an appropriate choice.',
 'In fictional offers, urgent small documents can take an available air service, while non-urgent bulk machinery can use an available sea route between ports. A village away from either terminal still needs a connecting movement. These classroom offers are not live schedules, fares or navigation instructions.',
 'Read urgency, size, route availability and delivery destination. Compare the whole chain, including transfer and final access. Justify the chosen mode using the stated conditions rather than a universal slogan about speed or cost.',[
 F('air transport','movement by aircraft between suitable terminals','An available aircraft carries urgent small documents.','Every aircraft journey requires no airport or terminal.','Air services depend on appropriate infrastructure and connections.'),
 F('water transport','movement by vessel over suitable water routes','A fictional sea service carries non-urgent bulk cargo.','Every river is navigable for every ship.','Depth, route and vessel requirements constrain navigation.'),
 F('intermodal transfer','a change between transport modes in a journey','A truck takes a landed shipment from a port to a warehouse.','A port is automatically the final destination of every good.','Many shipments need another mode after the port.'),
 F('mode suitability','fitness of a mode for the stated flow and conditions','A shipper compares urgency, bulk and terminal access.','One transport mode is best for every possible shipment.','Different flows and routes create different trade-offs.')],choose(12,[
 ('Invented offers: urgent small documents must arrive tomorrow; an air service meets that deadline and the offered sea service does not. Which fits?','The available air service',['The offered sea service','No transport because a message was sent','Any mode regardless of deadline'],['The stated sea offer misses the deadline.','Physical documents still need movement.','The deadline is a selection condition.'],'Use the actual offers, not an unconditional claim about all aircraft.'),
 ('Invented offers: non-urgent bulk cargo has port access and an affordable sea offer; the air offer exceeds the budget. Which fits these conditions?','The offered sea service',['The unaffordable air offer','A telephone call carrying the cargo','A railway absent from the offered routes'],['The air offer fails the stated budget.','Calls transmit information, not this cargo.','An unavailable route cannot be chosen.'],'Select a feasible offer that meets cargo and budget conditions.'),
 ('Cargo lands at a port but its warehouse is inland. What must the plan include?','An onward connection and transfer arrangements',['Assume the port is the warehouse','Ignore handling costs','Assume every road is navigable by ship'],['The final destination is inland.','Handling can affect total cost and time.','Ships use suitable water routes.'],'Compare the full journey rather than just its longest leg.')],TRA),TRA,[11])

unit(14,'Specialised transport: motorways and cableways','match specialised infrastructure to a stated need and limitation','transport modes and route constraints','pipeline networks',
 'A motorway is designed for controlled access and through movement, with connections concentrated at junctions. Its usefulness depends on demand and links to other roads; it does not provide a doorway to every settlement. A cableway moves supported cabins or loads along a cable route between terminals. It may cross difficult terrain but has capacity, weather, maintenance and safety constraints.',
 'An invented corridor has heavy through traffic and a proposal for controlled-access movement. A separate steep-slope site considers a cableway between fixed terminals. These proposals solve different movement problems. Neither model authorises local construction or states that a particular Cameroonian project is operating.',
 'Identify traffic type, terrain and access need. Explain why a specialised system may help, then state a limitation and the connecting service needed. Do not assume a motorway junction or cable terminal serves every doorstep.',[
 F('controlled access','entry and exit through designed junctions','An invented motorway proposal limits direct entry points.','Every adjacent field can open its own motorway entrance.','Controlled entry supports through movement but limits direct access.'),
 F('feeder connection','a local link to a larger transport route','A local road joins a through route at a junction.','A motorway eliminates all local access roads.','Through routes still need local connections.'),
 F('cableway','a system moving supported loads or cabins along a cable route','A fictional steep site links fixed terminals by cable.','A cableway can deliver freely to every hillside house.','Its fixed terminals and capacity limit the service area.'),
 F('specialisation limit','a condition restricting a system’s usefulness','A proposal checks traffic, maintenance and weather conditions.','A specialised system works best for every flow.','Fitness depends on the particular demand and constraints.')],choose(14,[
 ('An invented motorway bypass has no junction beside a village. What should a planner investigate?','The village’s feeder connection to an authorised junction',['Assume every home has direct entry','Replace all local roads with no connections','Ignore the village’s access needs'],['Controlled access limits direct entry.','Local journeys still need connections.','A bypass can change access for nearby people.'],'Assess through movement and local access separately.'),
 ('A fictional cableway links fixed hillside terminals. What is a relevant limitation?','Loads must reach and leave those terminals',['Every nearby doorstep is automatically served','No maintenance can be needed','Cableways have unlimited capacity'],['Fixed terminals constrain access.','Cables and equipment need maintenance.','Equipment and operating conditions limit capacity.'],'A terrain advantage does not remove terminal constraints.'),
 ('A proposed specialised route has little demand and high maintenance needs. What follows?','Its suitability needs a cost and demand assessment',['Its specialised name proves it is worthwhile','Every community must build one','Terrain and demand no longer matter'],['A name is not performance evidence.','Systems should match needs and resources.','Terrain and demand remain relevant.'],'Explain conditions rather than promising universal benefit.')],TRA),TRA,[12])

unit(15,'Pipelines','explain pipeline suitability and a related constraint','specialised fixed-route transport','global flows and telecommunications',
 'Pipelines carry suitable fluids, such as oil or gas, along fixed links using appropriate pressure and control systems. They can support continuous bulk movement, but require substantial construction, maintenance and monitoring. They do not carry every kind of freight or replace passenger transport. Leakage and route impacts require assessment; fixed infrastructure also makes changing destinations costly.',
 'The Chad–Cameroon petroleum pipeline project connects oil-producing areas in Chad with an offshore loading facility near Kribi in Cameroon. This is a route example, not a current flow, tariff or operating claim. A fictional liquid-fuel route can illustrate fixed-link benefits while a furniture shipment illustrates a cargo that cannot use that system.',
 'Ask whether the material is suitable for the system, whether origins and destinations fit the fixed route and how leakage would be detected and managed. Compare both operating advantages and construction or environmental constraints.',[
 F('fluid cargo','material capable of flowing through the designed pipeline system','An oil pipeline carries a suitable liquid product.','A liquid pipeline can carry finished chairs unchanged.','Cargo properties must match the transport system.'),
 F('fixed pipeline route','a constructed link between specified locations','A pipeline links a production area with a loading facility.','A pipeline can turn freely towards any new customer.','Changing a fixed route needs additional infrastructure.'),
 F('continuous bulk flow','sustained movement of suitable material through a system','An invented plant sends a fluid along a fixed link.','Continuous movement guarantees no interruption ever occurs.','Maintenance and operating conditions can interrupt flow.'),
 F('leakage risk','possible escape of material from the system','A proposal includes monitoring and response arrangements.','A buried pipeline can never affect the environment.','Leaks and construction can create environmental impacts.')],choose(15,[
 ('A fictional oil route has stable endpoints and suitable fluid cargo. Why might a pipeline be considered?','It can support bulk fluid movement along a fixed link',['It carries every passenger directly home','It carries all furniture without transformation','It avoids every construction cost'],['It is not a passenger system.','Finished furniture is unsuitable for this liquid pipeline.','Construction requires capital and land works.'],'Suitability depends on cargo and route conditions.'),
 ('A furniture seller wants to send assembled tables through an oil pipeline. What is the problem?','The cargo is unsuitable for that system',['The tables need only a telephone number','All transport modes accept every cargo','Pipelines are designed for doorstep furniture delivery'],['Contact information does not change cargo properties.','Systems have different cargo requirements.','A fixed fluid link does not serve tables.'],'Match physical properties to the designed system.'),
 ('A pipeline proposal claims burial removes all environmental concerns. What is missing?','Leakage, construction impacts and monitoring assessment',['Proof that fluids cannot leak','An assumption no land is used','A claim maintenance is unnecessary'],['Fluids can escape if a system fails.','Routes occupy and disturb land during construction.','Maintenance remains necessary.'],'Being underground does not eliminate impacts.')],TRA),TRA,[14])

unit(16,'Globalisation','trace a cross-border connection and explain an uneven effect','transport and communication systems','telecommunication networks and trade',
 'Globalisation is increasing interconnection across borders through goods, services, finance, people and information. It has historical roots; recent networks can intensify links without making distance or borders disappear. Production stages may take place in different countries. Opportunities and risks are uneven because capabilities, bargaining power, access and exposure differ.',
 'An invented Douala clothing business receives designs electronically, imports fabric, sews garments locally and sells some abroad. Information and physical goods use different networks in the same value chain. A delayed imported input can interrupt local work; a wider market can also create opportunities. Neither outcome applies identically to every firm.',
 'Draw the production stages, places and connecting flows. Explain a benefit and a vulnerability using this chain. Distinguish global interconnection from equal outcomes or an absence of rules and borders.',[
 F('global value chain','production stages linked across national borders','The fictional clothing chain combines imported fabric and local sewing.','Every finished product must be made entirely in a single country.','Different stages can be connected across places.'),
 F('information flow','movement of messages or data between places','A design file is sent to a clothing workshop.','A design file transports all the required fabric.','Information can coordinate production but materials still move.'),
 F('market opportunity','access to additional potential buyers','A fictional workshop reaches customers abroad.','Access to more buyers guarantees profit for every firm.','Demand, competition and costs still affect outcomes.'),
 F('interdependence risk','exposure to disruption through a connection','A delayed imported input interrupts the fictional workshop.','Cross-border links can never transmit disruption.','Connected stages can transmit delays as well as opportunities.')],choose(16,[
 ('An invented workshop receives designs online and fabric by ship. Which explanation fits?','Different networks connect information and materials in one production chain',['The online design replaces the fabric','The ship transports the design only','Borders have physically disappeared'],['Production still needs material inputs.','The stated ship carries fabric.','Connections do not remove national borders.'],'Trace each actual flow rather than treating them as identical.'),
 ('A fictional foreign supplier’s delay stops local sewing. What does this illustrate?','Interdependence can transmit supply disruption',['All international trade always stops production','Local workers caused every foreign delay','Every imported input is unnecessary'],['One case does not prove a universal effect.','The evidence identifies a supplier delay.','The process may depend on that input.'],'A linked chain can transmit a specific disruption.'),
 ('A small firm reaches new overseas buyers but faces strong competition. What is justified?','Global links create opportunities with uneven outcomes',['Every firm gains equally','Competition disappears across borders','No transport or payment arrangements are needed'],['Capabilities and costs differ.','Wider markets can increase competition.','Actual exchange still needs supporting arrangements.'],'Evaluate conditions instead of equating connection with guaranteed success.')],COM+REG),COM+REG,[15])

unit(17,'Telecommunications: signals and networks','identify how a telecommunication channel connects users and state a limitation','communication and globalisation','Cameroon networks and digital access',
 'Telecommunications transmits information over distance using signals. Networks may combine radio links, fibre-optic cables, satellites and switching equipment. A mobile handset can use a radio connection to a base station while later stages use other links. The device alone is not the entire network. Coverage, power, capacity and service conditions affect communication.',
 'In an invented Buea example, a trader’s phone sends an order through a mobile network; a distant receiver confirms the message. A broken connecting link can interrupt service even when the handset works. A fibre link carries information rather than cartons of goods. This lesson prepares network reasoning, not installation or account setup.',
 'Trace sender, local link, wider network and receiver. Identify the role of each medium and a possible point of failure. Distinguish a signal carrying information from the physical movement of the ordered goods.',[
 F('radio link','information transmission through electromagnetic waves without a cable on that link','A mobile handset connects to a nearby base station.','Every mobile-network stage must use the same local radio link.','Different network stages can use different media.'),
 F('fibre-optic link','information transmission using light through optical fibre','A fictional network carries data along a fibre cable.','Fibre carries the ordered sacks themselves.','The cable carries signals, not the cargo described in a message.'),
 F('satellite link','a communication path using an orbiting relay','A remote service uses a suitable satellite connection.','Satellites remove every ground equipment requirement.','Users still need suitable terminals and supporting systems.'),
 F('network reliability','the ability of a system to provide dependable communication','A damaged connecting link interrupts an otherwise working handset.','A working handset proves every network link is available.','Communication depends on connected system elements.')],choose(17,[
 ('A fictional phone works but its network’s connecting link fails. What follows?','The device alone cannot guarantee end-to-end communication',['The whole network must be inside the phone','The failure proves cargo was delivered','Messages need no connecting links'],['The phone is only one network element.','Communication failure does not establish delivery.','Distant users need a usable connection.'],'Reason about the whole path.'),
 ('A trader orders cartons over a fibre connection. What travels through the fibre?','Information encoded in signals',['The physical cartons','A road vehicle','Every worker from the factory'],['Goods need physical transport.','Vehicles do not travel inside the optical fibre.','People require a different movement system.'],'Telecommunications carries the order information.'),
 ('A route combines a local radio link with a fibre backbone. Is that possible in a network model?','Yes; different links can use different media',['No; every link must be radio','No; fibre can carry only raw materials','Yes; therefore network failures are impossible'],['A network can combine media.','Fibre carries information signals.','Mixed media do not remove failures.'],'Identify each link’s role rather than assuming one medium everywhere.')],COM),COM,[16])

unit(18,'Transport development in Cameroon: routes and nodes','read selected Cameroon transport links without inventing missing connections','road and rail networks','access inequalities and multimodal planning',
 'Cameroon’s transport system combines roads, rail and water or air connections. A node’s role depends on links, terminals and its surrounding activities. Camrail identifies Douala–Yaoundé and Yaoundé–Ngaoundéré rail connections. The schematic selects these links and a Douala–Kribi road connection; it is incomplete and not to scale. It gives no timetable, condition or current travel guarantee.',
 'The diagram distinguishes selected rail links from a road link and identifies Douala and Kribi as port nodes. It does not draw a rail connection to every port. A producer beyond these lines still needs access to a terminal. Actual travel planning requires current route, service and safety information beyond a classroom schematic.',
 'Read the legend before tracing a link. State what the drawing includes and what it cannot prove. Explain how a node could connect flows, then ask about local access, handling and service reliability.',[
 F('selected rail link','a named rail connection included in this schematic','The drawing links Douala and Yaoundé by a dashed rail line.','Every line in the schematic is railway.','The legend distinguishes road from rail.'),
 F('port node','a terminal connecting suitable land and water movements','Douala and Kribi appear as selected port nodes.','A port automatically has every mode of inland connection.','Each actual inland connection needs separate evidence.'),
 F('schematic limit','a restriction in what a simplified diagram can show','The selected drawing omits many routes and is not to scale.','A schematic supplies exact journey times.','A simplified network does not establish current travel performance.'),
 F('terminal access','the connection from a producer or customer to a terminal','A grower outside the rail corridor needs an onward link.','A railway line serves every field directly.','Fixed routes need local connections for dispersed origins.')],choose(18,[
 ('Which rail sequence is explicitly selected in the classroom diagram?','Douala–Yaoundé–Ngaoundéré',['Douala–Kribi–Ngaoundéré entirely by rail','Every village linked directly to Kribi by rail','No rail links are shown'],['The selected Douala–Kribi link is road.','The diagram does not show village rail links.','Its dashed lines represent selected rail.'],'Read selected links using the legend.'),
 ('The selected Douala–Kribi connection is grey and the legend says road. What can be concluded?','The schematic represents that selected connection as road',['It proves a rail link on that line','It gives today’s journey time','It includes every Cameroon road'],['The line’s legend says road.','No live time information is supplied.','The schematic is explicitly selective.'],'Use the legend without adding unsupported information.'),
 ('A shipment begins away from the drawn rail nodes. What does the diagram leave to investigate?','How it reaches a terminal and completes the final connection',['Assume every farm lies on a rail platform','Assume no transfer costs exist','Use the drawn line lengths as actual kilometres'],['The origin is away from the nodes.','Transfers may create costs.','The diagram is not to scale.'],'A national corridor is only part of a full journey.')],TRA),TRA,[10,17],figure=json.dumps(cameroon_links(),ensure_ascii=False))

unit(19,'Telecommunications: access and the digital divide','compare barriers to meaningful digital access and propose a matched response','signals and networks','Cameroon access planning and trade information',
 'The digital divide concerns unequal ability to access and use digital communication. Coverage is one condition; affordability, reliable power, suitable devices, skills, language and accessibility also matter. Owning a phone does not prove that a person can use a needed online service. Differences can occur within a town, between rural and urban places or among age and income groups.',
 'In an invented village comparison, the network reaches both households. One cannot afford regular data; another has access but needs help using the service language. Coverage expansion alone does not solve either problem. ITU’s meaningful-connectivity approach considers capabilities and usable access, rather than treating signal coverage as complete inclusion.',
 'Specify the barrier from the evidence. Match a response to affordability, skills, accessibility or reliability, and say what else remains. Do not infer ability, interest or income from residence alone.',[
 F('coverage barrier','absence of a usable network signal in a place','A fictional settlement has no available network connection.','Every access problem is caused only by poor motivation.','A missing connection can prevent access regardless of motivation.'),
 F('affordability barrier','a cost that prevents practical use','A household has coverage but cannot afford regular data.','A visible signal proves everyone can pay for service.','Coverage and ability to meet costs differ.'),
 F('skills barrier','difficulty using a service because relevant capabilities are missing','A user needs guided practice with the service interface.','Owning a device guarantees every digital skill.','Device ownership does not establish ability to use all services.'),
 F('accessibility barrier','a design or format obstacle excluding some users','A service lacks a usable format for a particular user.','One interface is automatically usable by everyone.','Design and format affect who can use a service.')],choose(19,[
 ('Both fictional households have signal; one cannot afford data. Which response targets the stated obstacle?','Assess affordable access arrangements',['Only build another mast without assessing costs','Assume the user has no interest','Count device ownership as full inclusion'],['Another mast alone does not address the stated cost.','The evidence concerns cost, not interest.','Ownership is only one condition.'],'Match the response to affordability.'),
 ('A fictional user can afford the service but cannot operate its interface. What most directly fits?','Relevant guided practice and usable design',['Assume all training is unnecessary','Measure only signal coverage','Infer that every neighbour has the same difficulty'],['The case identifies a capability or design obstacle.','Coverage does not test interface use.','Individual needs vary.'],'Investigate the actual task and user needs.'),
 ('A report measures only handset ownership. What additional evidence would test meaningful access?','Affordability, reliability, skills and usability',['Only the colour of the handset','Assume ownership proves every task is possible','Ignore users without suitable formats'],['Colour does not establish usable access.','Ownership does not measure every barrier.','Accessibility is part of inclusion.'],'Assess whether people can perform needed communication tasks.')],COM),COM,[17,18])

unit(20,'Transport development in Cameroon: connecting the full journey','evaluate a multimodal proposal using access, transfers and maintenance','Cameroon routes and access inequalities','map-network practicals',
 'Developing a transport system requires more than adding a major corridor. Local access, terminal capacity, maintenance, transfers and reliable services determine whether a complete journey works. Different users may gain or lose differently. A port improvement does not automatically repair inland roads; a railway corridor does not automatically provide collection from every farm.',
 'In an invented Cameroon proposal, produce travels by a local road to a depot and continues towards a port. The trunk connection improves, but the access road still floods seasonally. The whole-chain assessment includes spoilage, transfer handling and environmental effects as well as the improved link. No actual project performance or present road condition is claimed.',
 'Trace origin, access link, transfer node, trunk link and destination. Identify the weakest stated connection. Compare a proposed intervention against that constraint, then record remaining uncertainties and affected users.',[
 F('last-mile connection','the local access stage linking an origin or destination to a wider network','A fictional farm road joins a freight depot.','A trunk railway automatically reaches every farm gate.','Dispersed origins need local access to the main corridor.'),
 F('transfer handling','work and coordination when goods change vehicles or modes','Produce is moved from a local carrier at a depot.','Mode changes can never add delay or damage.','Handling can affect cost, time and condition.'),
 F('bottleneck','a constrained stage limiting the full journey','A seasonally blocked access link limits an improved corridor.','Improving any single link guarantees the entire chain works.','A remaining weak stage can restrict the full movement.'),
 F('whole-chain assessment','evaluation of connected stages and their combined effects','A proposal records access, transfer, trunk movement and destination needs.','The longest route segment alone determines every outcome.','Short links and transfers can materially affect a journey.')],choose(20,[
 ('An invented trunk route improves, but the farm access road is blocked. What limits delivery?','The remaining access bottleneck',['The trunk improvement proves delivery is guaranteed','A port name removes the blockage','Only straight-line distance matters'],['The chain still contains a blocked link.','A name does not create access.','Usable connections matter, not distance alone.'],'Trace every required stage.'),
 ('A fictional proposal changes from road to rail at a depot. What should its cost comparison include?','Transfer handling and connecting services',['Assume all transfers are free and instant','Only the colour of each vehicle','Ignore how goods reach the depot'],['Transfers may add cost or time.','Vehicle colour does not establish transport performance.','Origin access is part of the journey.'],'Include terminal and connecting stages.'),
 ('A fictional route benefits exporters but increases noise beside homes. What assessment fits?','Compare benefits and costs for the affected groups',['Exporter gains prove nobody bears a cost','Noise means no benefit can exist','Ignore households outside the firm'],['Benefits to one group do not remove costs to another.','Benefits and costs can coexist.','External effects concern people outside the firm.'],'Evaluate distribution as well as total activity.')],TRA),TRA,[18,19])

routes=[]
for ab,bd,ac,cd,block in [(10,15,20,15,'none'),(20,20,10,15,'none'),(15,10,20,20,'AB'),(20,15,10,10,'CD'),(10,20,15,10,'AB'),(25,10,10,20,'CD')]:
    top=ab+bd;bottom=ac+cd
    good='A–B–D' if block!='AB' and (block=='CD' or top<bottom) else 'A–C–D'
    other='A–C–D' if good=='A–B–D' else 'A–B–D'
    reason='That route uses the closed link.' if block!='none' else 'That open route has a longer total distance.'
    it=item('Invented map: transfers at nodes are allowed. Choose the shortest OPEN listed route from A to D. Use link distances, not drawn lengths.',good,[(other,reason),('Direct A–D','No direct A–D link is drawn.'),('No open route','At least one of A–B–D and A–C–D is open.')],f'Top route distance = {{{ab}}} + {{{bd}}} = {{{top}}} km. Bottom = {{{ac}}} + {{{cd}}} = {{{bottom}}} km. Closed link: {block}. Compare only usable routes; transfer time is not modelled.')
    it.update(ab=ab,bd=bd,ac=ac,cd=cd,block=block)
    # All displayed amounts are expression substitutions, including the working.
    routes.append(it)
routeq=qa(21,'network',2,routes,TRA,figure=expression(route_map(True)))
# Flatten banked map data for the figure expression without adding engine helpers.
routeq['vars'].update({k:{'expr':'X.'+k} for k in ['ab','bd','ac','cd']})
unit(21,'Practical: communication on maps','read a network legend and select a shortest open route with working','network links, transfers and constraints','trade flows and volume',
 'A network map represents nodes and links. Its legend identifies modes; link labels can give distances independently of the drawing’s scale. A route must use connected open links. When transfers are explicitly allowed, different modes can form a route. For a distance comparison add the distances of its links; do not infer time or fare without further data.',
 'The invented map uses solid roads and dashed rail links. Transfers at nodes are allowed. With no closure, A–B–D totals {10}+{15} = {25} km and A–C–D totals {20}+{15} = {35} km. The top route is shorter in this example. Other practice maps change distances or close a link. These are invented models, not travel instructions.',
 'Record each link’s mode and distance. Cross out any route containing a closed link; total each remaining route. State the shortest open listed route and its distance. Explain why a shorter-looking drawing or a non-existent direct link is not evidence.',[
 F('network legend','a key explaining symbols and line styles','The invented map uses solid road and dashed rail links.','A dashed line must always mean a closed route.','The given legend defines its meaning.'),
 F('connected route','a sequence of links joining the required nodes','A–B–D joins A to D through B.','An undrawn direct A–D link can be assumed.','A route needs links supported by the map.'),
 F('closure constraint','a restriction removing a link from usable routes','A marked closure excludes any route using that link.','The numerically shortest route is usable even when closed.','Feasibility must be checked before distance comparison.'),
 F('route distance','the sum of distances on the route’s links','Bih adds link labels rather than measuring the sketch.','A schematic’s drawn length always gives actual distance.','Labelled distances take priority in a not-to-scale model.')],routeq,TRA,[20],figure=expression(route_map(False)),example=L.worked({},'No links are closed. AB is {10} km, BD {15} km, AC {20} km and CD {15} km. Transfers are allowed.', ['A–B–D: {10}+{15} = {25} km.','A–C–D: {20}+{15} = {35} km.','Compare open listed routes only.'],'A–B–D is shorter at {25} km.'))

unit(22,'Volume of trade','distinguish physical trade quantity from money value and calculate a comparable total','transport flows and network maps','regional trade arrangements',
 'Trade can be measured as physical quantities or as monetary values. A total physical tonnage requires compatible units and a specified period and boundary. Adding exports and imports gives a total flow measure when defined that way; subtracting gives a balance instead. Monetary trade value can change with prices even when physical quantities do not. Published volume indices may use constant-price methods rather than raw tonnage.',
 'In an invented port-month record, exports weigh {120} tonnes and imports {180} tonnes. Combined handled trade is {120+180} tonnes. This does not measure export earnings, an export-minus-import balance or value added. If prices change while these weights stay fixed, trade money values may change without the physical tonnage changing.',
 'Name the measure, units, area and period before calculating. Add compatible physical quantities for the stated combined flow. Do not add tonnes to CFA francs or assume every published use of volume means a simple total weight.',[
 F('physical quantity','an amount measured in a physical unit','A record states tonnes moved in a month.','Tonnes are a monetary price unit.','Weight differs from money value.'),
 F('trade value','a monetary measure of traded goods or services','A report records a shipment’s money value.','An unchanged weight guarantees unchanged money value.','Prices can change independently of physical quantity.'),
 F('combined trade flow','exports plus imports under the stated definition','A fictional record adds compatible outward and inward tonnage.','Combined flow is always exports minus imports.','Addition measures this defined total; subtraction measures a difference.'),
 F('comparison basis','the boundary, period and units making a comparison meaningful','Bih compares the same port-month and unit.','Tonnes and currency may be added directly.','Compatible definitions and units are necessary.')],number(22,'tonnage','Invented monthly port record: exports {x} tonnes and imports {m} tonnes. Find combined export-plus-import tonnage.','x+m',{'x':{'pick':[80,120,160,200]},'m':{'pick':[100,180,220]}},['Combined flow = exports + imports.','{x} + {m} = {x+m} tonnes.'],[('x-m','Subtraction measures a difference, not the requested combined flow.'),('x','Exports alone omit imports.')],REG,'tonnes'),REG,[21])

unit(23,'Trade blocs: forms and distinguishing features','classify an invented arrangement from its stated integration features','trade measures and cross-border connections','regional opportunities and limitations',
 'A trade bloc is an arrangement between economies to organise aspects of exchange. In a simplified comparison, a free-trade area removes agreed internal trade barriers while members retain their own external tariffs. A customs union adds a common external tariff. A common market adds freer factor movement. A monetary union shares monetary arrangements. Actual agreements vary and implementation can differ from stated aims.',
 'Invented Region K removes agreed internal tariffs but keeps separate external tariffs: it fits our free-trade-area model. Region L also adopts a common external tariff: it fits the customs-union model. Neither description proves all border checks disappear or that every person has unrestricted movement. These are feature cards, not current rules for travellers or traders.',
 'Underline the distinguishing feature. Separate internal trade from treatment of non-members, and goods movement from labour or capital movement. Use the stated model rather than assuming every bloc follows an identical compulsory sequence.',[
 F('free-trade area','an arrangement removing agreed internal trade barriers while retaining separate external tariffs','Invented Region K retains members’ separate external tariffs.','Every free-trade area must have a single external tariff.','Separate external tariffs distinguish the simplified free-trade-area model.'),
 F('customs union','an arrangement combining internal trade liberalisation with a common external tariff','Invented Region L agrees a common tariff towards non-members.','A common external tariff means no common trade policy feature exists.','Shared external tariff treatment is a distinguishing feature.'),
 F('common market','an arrangement adding freer movement of factors of production','An invented agreement includes freer labour and capital movement.','Goods liberalisation alone proves full factor mobility.','Movement of factors is a further feature, not implied by goods trade alone.'),
 F('monetary union','an arrangement sharing a currency or monetary institutions','An invented region shares a currency and monetary authority.','Sharing monetary arrangements guarantees identical incomes everywhere.','Common money does not eliminate differences in productivity or income.')],choose(23,[
 ('Invented members remove agreed internal tariffs but keep separate external tariffs. Which simplified category fits?','Free-trade area',['Customs union with a common external tariff','Monetary union proved by this fact alone','No trade arrangement is possible'],['A common external tariff is not stated.','Currency sharing is not stated.','Internal liberalisation can form an arrangement.'],'Classify the features actually given.'),
 ('Invented members liberalise internal goods trade and adopt a common external tariff. Which distinguishing category fits?','Customs union',['Free-trade area retaining separate external tariffs','A telephone network','A guaranteed equal-income region'],['Separate external tariffs contradict the stated common tariff.','The features describe trade institutions.','Tariff arrangements do not guarantee equal incomes.'],'The shared external tariff distinguishes this model.'),
 ('An invented arrangement adds freer labour and capital movement to goods integration. Which feature is being added?','Common-market factor movement',['Only a shared road surface','Automatic elimination of every border procedure','Proof all members have identical wages'],['Infrastructure alone is not factor-movement policy.','Agreements can retain procedures and conditions.','Freer factor movement does not guarantee wage identity.'],'Distinguish production factors from goods alone.')],REG),REG,[22])

unit(24,'Trade blocs: opportunities, implementation and limits','assess a regional trade proposal and calculate an invented within-region share','forms of trade integration','later trade case studies and development comparisons',
 'Regional integration can widen markets, support production links and coordinate some rules. Benefits depend on implementation, infrastructure and firms’ capabilities. Trade creation replaces a higher-cost domestic source with a lower-cost partner; trade diversion shifts purchases from an efficient non-member towards a less efficient member because of preferences. An agreement’s objectives are not proof that all barriers have disappeared.',
 'CEMAC provides a regional institutional example for Cameroon. The AfCFTA agreement seeks a wider African market and progressive liberalisation; its objectives do not mean identical implementation everywhere. In an invented regional record, within-region exports are {30} units out of total exports of {120}; the share is {30/120*100} per cent. These are not official statistics.',
 'Separate an institution’s aim from evidence of results. Check internal and external costs before naming trade creation or diversion. For the stated within-region export share, divide within-region exports by all exports and multiply by {100}; use the same period and valuation basis.',[
 F('market enlargement','access to a wider potential customer base','An invented producer can seek customers in partner economies.','A larger potential market guarantees every producer succeeds.','Capabilities, competition and implementation affect results.'),
 F('trade creation','replacement of higher-cost domestic production by a lower-cost partner supply','An invented model switches to a lower-cost partner source.','Every partner purchase is automatically trade diversion.','Compare the previous and new sources and their costs.'),
 F('trade diversion','a preference-induced shift from an efficient outside source to a less efficient partner','An invented tariff preference changes sourcing towards a higher-cost partner.','A regional preference can never distort source selection.','Preferences may alter the relative price of member and non-member supplies.'),
 F('implementation gap','a difference between agreed objectives and realised conditions','An agreement exists but a fictional border procedure still delays goods.','Signing an agreement proves every barrier is gone.','Institutions and actual practices must be assessed separately.')],number(24,'share','Invented record on the same valuation basis: within-region exports {inside}; all exports {total}. Find the within-region export share as a percentage.','inside/total*100',{'total':{'pick':[100,200,400]},'pct':{'pick':[10,20,25,40,50]},'inside':'total*pct/100'},['Share = within-region exports ÷ all exports × {100}.','{inside} ÷ {total} × {100} = {inside/total*100} per cent.'],[('inside/total','That is a fraction; multiply by a hundred to express it as a percentage.'),('total-inside','That is an outside-region amount, not a share.')],REG,'per cent'),REG,[23])

